// Generated by scripts/traducir-focos.mjs. Spanish source and calculations are shared.
"use client";

import { useEffect, useRef, useState } from "react";
import { ExploradorEnlazado } from "@/presentation-en/components/explorador/ExploradorEnlazado";
import type { Modo } from "@/presentation-en/lib/focos/modo";
import { DemoEscenario } from "@/presentation-en/components/sitio/DemoEscenario";
import estilos from "@/components/sitio/ExploracionTemporal.module.css";

type Props = { desde: number; hasta: number; modo: Modo; nota: string };

export function ExploracionTemporal({ desde, hasta, modo, nota }: Props) {
  const [futuro, setFuturo] = useState(false);
  const [espacio, setEspacio] = useState(80);
  const tarjeta = useRef<HTMLDivElement>(null);
  const mostrarFuturo = futuro;

  useEffect(() => {
    const elemento = tarjeta.current;
    if (!elemento) return;
    const medir = () => setEspacio(Math.ceil(elemento.getBoundingClientRect().height) + 20);
    const observador = new ResizeObserver(medir);
    observador.observe(elemento);
    medir();
    return () => observador.disconnect();
  }, [mostrarFuturo]);

  const selector = (
    <div ref={tarjeta} className={estilos.tarjeta}>
      <div className={estilos.opciones} role="group" aria-label="Exploration period">
        <button type="button" title={`Recorded data from ${desde} to ${hasta}`} aria-pressed={!mostrarFuturo} onClick={() => setFuturo(false)}> Historical </button>
          <button type="button" title="Simulated scenario for the next ten years" aria-pressed={mostrarFuturo} onClick={() => setFuturo(true)}> Future </button>
      </div>
    </div>
  );

  return (
    <section id="explorar" className="seccion seccion-alterna" aria-labelledby="titulo-explorar">
      <div className="contenedor">
        <div className="seccion-cabeza">
          <h2 id="titulo-explorar">{mostrarFuturo ? "What do the data tell us about the future?" : "Explore where and when they occur"}</h2>
          <p>{mostrarFuturo
            ? (modo === "incendios"
              ? "Explore a monthly scenario based on historical detections associated with burned areas. Points are simulated, not confirmed future fires or individual events."
              : "Explore a possible monthly evolution of thermal hotspots in San Luis over ten years. Locations are simulated, not confirmed future fires.")
            : "Explore recorded detections: choose a year and month, filter by department, or play the record month by month."}</p>
        </div>
        {mostrarFuturo ? (
          <div className={estilos.futuro}>
            <div className={estilos.selectorFuturo}>{selector}</div>
            <DemoEscenario key={modo} modo={modo} integrado espacioControles={espacio} />
          </div>
        ) : (
          <>
            <p className={`nota ${estilos.nota}`}>{nota}</p>
            <ExploradorEnlazado desde={desde} hasta={hasta} modo={modo} panelInicio={selector} />
          </>
        )}
      </div>
    </section>
  );
}
